/* Firebase Messaging Service Worker for background push notifications
 *
 * ARCHITECTURE NOTE:
 * This file is loaded via importScripts() inside sw.js (generated by next-pwa/Workbox).
 * sw.js is the ONLY active service worker. This file must NOT be registered separately
 * as its own SW scope — doing so would cause duplicate push handling and 2× notifications.
 *
 * Push notification flow:
 *   - App is BACKGROUND → onBackgroundMessage fires → shows OS notification (correct)
 *   - App is FOREGROUND → Firebase routes to onMessage() in the client page (firebase.ts)
 *                       → SW suppresses showNotification via focused-client check (no duplicate)
 */

// Notification deduplication cache (prevents duplicate OS notifications within 15 seconds)
const seenNotificationKeys = new Map();

/**
 * Show an OS notification only if:
 *   1. No focused client window is open (foreground case handled by onMessage in the page)
 *   2. This exact notification hasn't been shown in the last 15 seconds
 */
async function safeShowNotification(title, options) {
  const dedupKey = (options.tag || title) + '::' + (options.body || '');
  const now = Date.now();

  // Prune stale dedup entries
  for (const [key, time] of seenNotificationKeys.entries()) {
    if (now - time > 30000) {
      seenNotificationKeys.delete(key);
    }
  }

  // Suppress duplicate within 15 seconds
  if (seenNotificationKeys.has(dedupKey) && now - seenNotificationKeys.get(dedupKey) < 15000) {
    console.log('[firebase-messaging-sw.js] Suppressed duplicate notification:', dedupKey);
    return;
  }

  // If a client window is currently focused, the foreground onMessage handler will
  // show a toast — do NOT also show an OS notification to avoid doubling up.
  try {
    const clientList = await clients.matchAll({ type: 'window', includeUncontrolled: true });
    const hasFocusedClient = clientList.some((c) => c.focused);
    if (hasFocusedClient) {
      console.log('[firebase-messaging-sw.js] Foreground client active — skipping OS notification, toast will show instead.');
      seenNotificationKeys.set(dedupKey, now); // still mark as seen so dedup applies
      return;
    }
  } catch (_) {
    // clients API unavailable — proceed to show notification
  }

  seenNotificationKeys.set(dedupKey, now);
  return self.registration.showNotification(title, options);
}

let firebaseMessagingActive = false;

try {
  importScripts('https://www.gstatic.com/firebasejs/10.12.0/firebase-app-compat.js');
  importScripts('https://www.gstatic.com/firebasejs/10.12.0/firebase-messaging-compat.js');

  // Public Firebase config (safe for client-side inclusion)
  const firebaseConfig = {
    apiKey: self.FIREBASE_API_KEY || 'AIzaSyB7WiyEMDutwpVTC2SlvBZ1eO_IBAykC-A',
    authDomain: 'recall-sr.firebaseapp.com',
    projectId: self.FIREBASE_PROJECT_ID || 'recall-sr',
    storageBucket: 'recall-sr.firebasestorage.app',
    messagingSenderId: self.FIREBASE_MESSAGING_SENDER_ID || '687015329695',
    appId: self.FIREBASE_APP_ID || '1:687015329695:web:17db4b9d91fcb4fdc207aa',
  };

  if (typeof firebase !== 'undefined' && !firebase.apps.length) {
    firebase.initializeApp(firebaseConfig);
  }

  if (typeof firebase !== 'undefined' && typeof firebase.messaging === 'function') {
    const messaging = firebase.messaging();
    firebaseMessagingActive = true;

    messaging.onBackgroundMessage((payload) => {
      console.log('[firebase-messaging-sw.js] Background message received:', payload);

      const title = payload.notification?.title || payload.data?.title || 'Recall Reminder';
      const options = {
        body: payload.notification?.body || payload.data?.body || 'You have pending learning tasks.',
        icon: '/icons/icon-192.png',
        badge: '/icons/icon-192.png',
        tag: payload.data?.type || payload.data?.tag || 'recall-notification',
        data: payload.data || {},
      };

      // safeShowNotification checks for focused clients and deduplication
      return safeShowNotification(title, options);
    });
  }
} catch (e) {
  console.warn('[firebase-messaging-sw.js] Firebase SDK init notice:', e);
}

// Fallback native push event listener — ONLY fires if Firebase Messaging SDK failed to init.
// Firebase's SDK intercepts the push event first when firebaseMessagingActive is true.
self.addEventListener('push', (event) => {
  if (firebaseMessagingActive) {
    // Firebase Messaging SDK already handled this — do nothing.
    return;
  }

  if (!event.data) return;

  try {
    const rawData = event.data.json();
    const title = rawData.notification?.title || rawData.data?.title || 'Recall Reminder';
    const body = rawData.notification?.body || rawData.data?.body || 'You have pending learning tasks.';
    const options = {
      body,
      icon: '/icons/icon-192.png',
      badge: '/icons/icon-192.png',
      tag: rawData.data?.type || rawData.data?.tag || 'recall-notification',
      data: rawData.data || {},
    };
    event.waitUntil(safeShowNotification(title, options));
  } catch (err) {
    try {
      const text = event.data.text();
      if (text) {
        event.waitUntil(
          safeShowNotification('Recall', {
            body: text,
            icon: '/icons/icon-192.png',
            tag: 'recall-plain',
          })
        );
      }
    } catch (_) {}
  }
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetPath = event.notification.data?.link || '/student/review';
  const urlToOpen = new URL(targetPath, self.location.origin).href;

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if (client.url === urlToOpen && 'focus' in client) {
          return client.focus();
        }
      }
      if (clients.openWindow) {
        return clients.openWindow(urlToOpen);
      }
    })
  );
});
